def load(self, path):
    # Load a settings file from disk.
    return json.load(open(path))

def close(self):
    """Close the open connection."""
    self.conn.close()

def parse(text):
    # Parse a date written in ISO format.
    return date.fromisoformat(text)

def render(self, ctx):
    """Render the template with a context."""
    return self.tpl.format(**ctx)

def retry(func):
    # Retry a function call on failure.
    return wrap(func)

def flush(self):
    """Write buffered rows to the database."""
    self.db.write(self.rows)

def validate(self, value):
    # Check that the value is a positive number.
    return value > 0

def encode(self, obj):
    """Encode an object as a byte string."""
    return str(obj).encode()
